namespace RuntimeCheck;

use Eleph\Runtime\Catalogue\EntityCatalogue;
use Eleph\Runtime\Mutation\EntitySideEffects;
use Eleph\Runtime\Mutation\Managed;
use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Policy\EntityReadPolicies;
use Eleph\Runtime\Policy\EntityWritePolicies;
use Eleph\Runtime\Policy\NoPolicies;
use Eleph\Runtime\Query\Hydrator;
use Eleph\Runtime\Storage\DeletionRule;
use Eleph\Runtime\Verification\EntityVerifiers;
use Psr\Container\ContainerInterface;
use RuntimeCheck\Page\Contract\PagePublishAction;
use RuntimeCheck\Page\PageDeleter;
use RuntimeCheck\Page\PageFinder;
use RuntimeCheck\Page\PageHydrator;
use RuntimeCheck\Page\PageInput;
use RuntimeCheck\Page\PageMutator;
use RuntimeCheck\Page\PageReadPolicies;
use RuntimeCheck\Page\PageSideEffects;
use RuntimeCheck\Page\PageVerifiers;
use RuntimeCheck\User\UserDeleter;
use RuntimeCheck\User\UserHydrator;
use RuntimeCheck\User\UserInput;
use RuntimeCheck\User\UserMutator;
use RuntimeCheck\User\UserSideEffects;
use RuntimeCheck\User\UserVerifiers;
use RuntimeException;

/**
 * What the runtime knows about this project's entities.
 */
final readonly class Catalogue implements EntityCatalogue
{
    public function __construct(
        private ContainerInterface $container,
    ) {
    }

    /**
     * @return list<string>
     */
    public function entities(): array
    {
        return ['Page', 'User'];
    }

    /**
     * @return Hydrator<object>
     */
    public function hydrator(string $entity): Hydrator
    {
        $service = match ($entity) {
            'Page' => $this->container->get(PageHydrator::class),
            'User' => $this->container->get(UserHydrator::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof Hydrator);

        return $service;
    }

    public function verifiers(string $entity): EntityVerifiers
    {
        $service = match ($entity) {
            'Page' => $this->container->get(PageVerifiers::class),
            'User' => $this->container->get(UserVerifiers::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntityVerifiers);

        return $service;
    }

    public function sideEffects(string $entity): EntitySideEffects
    {
        $service = match ($entity) {
            'Page' => $this->container->get(PageSideEffects::class),
            'User' => $this->container->get(UserSideEffects::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntitySideEffects);

        return $service;
    }

    private function readPoliciesPageReadPolicies(): EntityReadPolicies
    {
        $policies = $this->container->get(PageReadPolicies::class);

        assert($policies instanceof PageReadPolicies);

        return $policies;
    }

    public function readPolicies(string $entity): EntityReadPolicies
    {
        return match ($entity) {
            'Page' => $this->readPoliciesPageReadPolicies(),
            'User' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    public function writePolicies(string $entity): EntityWritePolicies
    {
        return match ($entity) {
            'Page' => new NoPolicies(),
            'User' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return array<string, string> "Entity.edge" => target entity
     */
    public function edgeTargets(): array
    {
        return [];
    }

    /**
     * @return array<string, string> "Entity.field" => declared type
     */
    public function fieldTypes(): array
    {
        return [
            'Page.amount' => 'Amount',
        ];
    }

    /**
     * @return list<string>
     */
    public function fieldNames(string $entity): array
    {
        return match ($entity) {
            'Page' => ['title', 'slug', 'content', 'excerpt', 'status', 'publishedAt', 'enquiryUrl', 'active', 'zero', 'disabled', 'metadata', 'createdAt', 'rank', 'amount'],
            'User' => ['username', 'role', 'active'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredFields(string $entity): array
    {
        return match ($entity) {
            'Page' => ['title', 'slug'],
            'User' => ['username'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function nonNullableFields(string $entity): array
    {
        return match ($entity) {
            'Page' => ['title', 'slug', 'content', 'excerpt', 'status', 'active', 'zero', 'disabled', 'metadata', 'createdAt', 'rank', 'amount'],
            'User' => ['username', 'role', 'active'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredEdges(string $entity): array
    {
        return match ($entity) {
            'Page' => [],
            'User' => [],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function uniqueFields(string $entity): array
    {
        return match ($entity) {
            'Page' => [],
            'User' => [],
            default => [],
        };
    }

    /**
     * @return array<string, Managed> "Entity.field" => policy
     */
    public function managedFields(): array
    {
        return [
            'Page.createdAt' => Managed::Created,
        ];
    }

    /**
     * @return list<DeletionRule>
     */
    public function deletionRules(string $entity): array
    {
        return match ($entity) {
            'Page' => PageDeleter::rules(),
            'User' => UserDeleter::rules(),
            default => [],
        };
    }

    public function finder(string $entity): object
    {
        $finder = match ($entity) {
            'Page' => $this->container->get(PageFinder::class),
            default => throw new RuntimeException(sprintf('%s declares no queries.', $entity)),
        };

        assert(is_object($finder));

        return $finder;
    }

    public function mutatorFor(string $entity, MutationBuffer $buffer): object
    {
        return match ($entity) {
            'Page' => new PageMutator($buffer, $this->resolve(PagePublishAction::class)),
            'User' => new UserMutator($buffer),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return list<string>
     */
    public function queryArguments(string $entity, string $query): array
    {
        return match ($entity . '.' . $query) {
            'Page.bySlug' => ['slug'],
            'Page.search' => ['limit'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function actionArguments(string $entity, string $action): array
    {
        return match ($entity . '.' . $action) {
            'Page.publish' => ['at'],
            default => [],
        };
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodePageInputActionArguments(string $action, array $args): array
    {
        $input = $this->container->get(PageInput::class);

        assert($input instanceof PageInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeUserInputActionArguments(string $action, array $args): array
    {
        $input = $this->container->get(UserInput::class);

        assert($input instanceof UserInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeActionArguments(string $entity, string $action, array $args): array
    {
        return match ($entity) {
            'Page' => $this->decodePageInputActionArguments($action, $args),
            'User' => $this->decodeUserInputActionArguments($action, $args),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @param array<string, mixed> $input
     */
    public function apply(string $entity, MutationBuffer $buffer, array $input): void
    {
        $applier = match ($entity) {
            'Page' => $this->container->get(PageInput::class),
            'User' => $this->container->get(UserInput::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert(is_object($applier) && method_exists($applier, 'apply'));

        $applier->apply($buffer, $input);
    }

    /**
     * Everything the application must implement before it can start.
     *
     * @return list<string>
     */
    public function contracts(): array
    {
        return ['RuntimeCheck\\Page\\Contract\\PageBySlugQuery', 'RuntimeCheck\\Page\\Contract\\PageEnquiryUrlVerifier', 'RuntimeCheck\\Page\\Contract\\PagePublicReadPolicy', 'RuntimeCheck\\Page\\Contract\\PagePublishAction', 'RuntimeCheck\\Page\\Contract\\PagePublishedAtVerifier', 'RuntimeCheck\\Page\\Contract\\PageSearchQuery', 'RuntimeCheck\\Type\\AmountReadProcessor', 'RuntimeCheck\\Type\\AmountWriteProcessor'];
    }

    /**
     * @template T of object
     * @param class-string<T> $class
     * @return T
     */
    private function resolve(string $class): object
    {
        $service = $this->container->get($class);

        assert($service instanceof $class);

        return $service;
    }
}

namespace RuntimeCheck\Enum;

enum Role: int
{
    case Editor = 0;
    case Viewer = 1;
}

namespace RuntimeCheck\Enum;

enum Status: string
{
    case Draft = 'draft';
    case Published = 'published';
}

namespace RuntimeCheck\Page\Contract;

use RuntimeCheck\Page\Page;

/**
 * Backs PageFinder::bySlug().
 */
interface PageBySlugQuery
{
    public function find(string $slug): ?Page;
}

namespace RuntimeCheck\Page\Contract;

use Eleph\Runtime\Verification\Verification;
use RuntimeCheck\Page\PageMutationContext;

/**
 * Entity-specific rules for Page::enquiryUrl.
 *
 * Runs before the type processor, and both run even when this fails, so
 * violations from both tiers arrive together.
 */
interface PageEnquiryUrlVerifier
{
    public function verify(?string $value, PageMutationContext $context): Verification;
}

namespace RuntimeCheck\Page\Contract;

use Eleph\Runtime\Policy\PolicyDecision;
use Eleph\Runtime\Policy\Viewer;
use RuntimeCheck\Page\Page;

/**
 * Application policy public for Page.
 */
interface PagePublicReadPolicy
{
    public function decide(Page $entity, Viewer $viewer): PolicyDecision;
}

namespace RuntimeCheck\Page\Contract;

use DateTimeImmutable;
use RuntimeCheck\Page\PagePublishContext;

/**
 * Backs PageMutator::publish().
 *
 * The context exposes only what publish declares it writes, so this cannot
 * touch anything the spec does not say it touches.
 */
interface PagePublishAction
{
    public function handle(PagePublishContext $context, DateTimeImmutable $at): void;
}

namespace RuntimeCheck\Page\Contract;

use DateTimeImmutable;
use Eleph\Runtime\Verification\Verification;
use RuntimeCheck\Page\PageMutationContext;

/**
 * Entity-specific rules for Page::publishedAt.
 *
 * Runs before the type processor, and both run even when this fails, so
 * violations from both tiers arrive together.
 */
interface PagePublishedAtVerifier
{
    public function verify(?DateTimeImmutable $value, PageMutationContext $context): Verification;
}

namespace RuntimeCheck\Page\Contract;

use Eleph\Runtime\Query\EntityQuery;
use RuntimeCheck\Page\Page;

/**
 * Backs PageFinder::search().
 */
interface PageSearchQuery
{
    /**
     * @return EntityQuery<Page>
     */
    public function find(?int $limit = null): EntityQuery;
}

namespace RuntimeCheck\Page;

use DateTimeImmutable;
use Eleph\Runtime\Identity\EntityId;
use RuntimeCheck\Enum\Status;
use RuntimeCheckType\Amount;

/**
 * Page, as stored.
 */
final class Page
{
    private function __construct(
        private readonly EntityId $id,
        private readonly string $title,
        private readonly string $slug,
        private readonly string $content,
        private readonly string $excerpt,
        private readonly Status $status,
        private readonly ?DateTimeImmutable $publishedAt,
        private readonly ?string $enquiryUrl,
        private readonly bool $active,
        private readonly int $zero,
        private readonly bool $disabled,
        private readonly array $metadata,
        private readonly DateTimeImmutable $createdAt,
        private readonly int $rank,
        private readonly Amount $amount,
    ) {
    }

    public function getId(): EntityId
    {
        return $this->id;
    }

    public function getTitle(): string
    {
        return $this->title;
    }

    public function getSlug(): string
    {
        return $this->slug;
    }

    public function getContent(): string
    {
        return $this->content;
    }

    public function getExcerpt(): string
    {
        return $this->excerpt;
    }

    public function getStatus(): Status
    {
        return $this->status;
    }

    public function getPublishedAt(): ?DateTimeImmutable
    {
        return $this->publishedAt;
    }

    public function getEnquiryUrl(): ?string
    {
        return $this->enquiryUrl;
    }

    public function getActive(): bool
    {
        return $this->active;
    }

    public function getZero(): int
    {
        return $this->zero;
    }

    public function getDisabled(): bool
    {
        return $this->disabled;
    }

    public function getMetadata(): array
    {
        return $this->metadata;
    }

    public function getCreatedAt(): DateTimeImmutable
    {
        return $this->createdAt;
    }

    public function getRank(): int
    {
        return $this->rank;
    }

    public function getAmount(): Amount
    {
        return $this->amount;
    }

    public static function of(
        EntityId $id,
        string $title,
        string $slug,
        string $content,
        string $excerpt,
        Status $status,
        ?DateTimeImmutable $publishedAt,
        ?string $enquiryUrl,
        bool $active,
        int $zero,
        bool $disabled,
        array $metadata,
        DateTimeImmutable $createdAt,
        int $rank,
        Amount $amount,
    ): self {
        return new self($id, $title, $slug, $content, $excerpt, $status, $publishedAt, $enquiryUrl, $active, $zero, $disabled, $metadata, $createdAt, $rank, $amount);
    }
}

namespace RuntimeCheck\Page;

use Eleph\Runtime\Identity\EntityId;
use Eleph\Runtime\Mutation\Deletion;
use Eleph\Runtime\Storage\DeletionRule;
use Eleph\Runtime\UnitOfWork\UnitOfWork;

/**
 * Removes a Page, and whatever its edges say goes with it.
 */
final class PageDeleter
{
    public function __construct(
        private readonly UnitOfWork $work,
    ) {
    }

    /**
     * Registers the removal. Nothing happens until the unit of work commits.
     */
    public function delete(EntityId $id): void
    {
        $this->work->delete(new Deletion('Page', $id));
    }

    /**
     * @return list<DeletionRule>
     */
    public static function rules(): array
    {
        return [];
    }
}

namespace RuntimeCheck\Page;

use Eleph\Runtime\Query\EntityQuery;
use RuntimeCheck\Page\Contract\PageBySlugQuery;
use RuntimeCheck\Page\Contract\PageSearchQuery;

/**
 * Collection-level queries over Page.
 */
final class PageFinder
{
    public function __construct(
        private readonly PageBySlugQuery $bySlugQuery,
        private readonly PageSearchQuery $searchQuery,
    ) {
    }

    public function bySlug(string $slug): ?Page
    {
        return $this->bySlugQuery->find($slug);
    }

    /**
     * @return EntityQuery<Page>
     */
    public function search(?int $limit = null): EntityQuery
    {
        return $this->searchQuery->find($limit);
    }
}

namespace RuntimeCheck\Page;

use DateTimeImmutable;
use Eleph\Runtime\Query\EdgeLoader;
use Eleph\Runtime\Query\Hydrator;
use Eleph\Runtime\Query\ValueDecoder;
use Eleph\Runtime\Storage\Record;
use RuntimeCheck\Enum\Status;
use RuntimeCheck\Type\AmountReadProcessor;
use RuntimeCheckType\Amount;

/**
 * Builds a Page from a stored row.
 *
 * @implements Hydrator<Page>
 */
final readonly class PageHydrator implements Hydrator
{
    public function __construct(
        private ValueDecoder $decode,
        private AmountReadProcessor $amountReader,
    ) {
    }

    public function hydrate(Record $record, EdgeLoader $edges): Page
    {
        return Page::of(
            $record->id,
            $this->title($record),
            $this->slug($record),
            $this->content($record),
            $this->excerpt($record),
            $this->status($record),
            $this->publishedAt($record),
            $this->enquiryUrl($record),
            $this->active($record),
            $this->zero($record),
            $this->disabled($record),
            $this->metadata($record),
            $this->createdAt($record),
            $this->rank($record),
            $this->amount($record),
        );
    }

    private function title(Record $record): string
    {
        $value = $record->value('title');

        return $this->decode->string($value, 'Page.title');
    }

    private function slug(Record $record): string
    {
        $value = $record->value('slug');

        return $this->decode->string($value, 'Page.slug');
    }

    private function content(Record $record): string
    {
        $value = $record->value('content');

        return $this->decode->string($value, 'Page.content');
    }

    private function excerpt(Record $record): string
    {
        $value = $record->value('excerpt');

        return $this->decode->string($value, 'Page.excerpt');
    }

    private function status(Record $record): Status
    {
        $value = $record->value('status');

        return $this->decode->enum(Status::class, $value, 'Page.status');
    }

    private function publishedAt(Record $record): ?DateTimeImmutable
    {
        $value = $record->value('publishedAt');

        return null === $value ? null : $this->decode->datetime($value, 'Page.publishedAt');
    }

    private function enquiryUrl(Record $record): ?string
    {
        $value = $record->value('enquiryUrl');

        return null === $value ? null : $this->decode->string($value, 'Page.enquiryUrl');
    }

    private function active(Record $record): bool
    {
        $value = $record->value('active');

        return $this->decode->bool($value, 'Page.active');
    }

    private function zero(Record $record): int
    {
        $value = $record->value('zero');

        return $this->decode->int($value, 'Page.zero');
    }

    private function disabled(Record $record): bool
    {
        $value = $record->value('disabled');

        return $this->decode->bool($value, 'Page.disabled');
    }

    private function metadata(Record $record): array
    {
        $value = $record->value('metadata');

        return $this->decode->json($value, 'Page.metadata');
    }

    private function createdAt(Record $record): DateTimeImmutable
    {
        $value = $record->value('createdAt');

        return $this->decode->datetime($value, 'Page.createdAt');
    }

    private function rank(Record $record): int
    {
        $value = $record->value('rank');

        return $this->decode->int($value, 'Page.rank');
    }

    private function amount(Record $record): Amount
    {
        $value = $record->value('amount');

        return $this->amountReader->read($this->decode->string($value, 'Page.amount'));
    }
}

namespace RuntimeCheck\Page;

use DateTimeImmutable;
use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Query\ValueDecoder;
use InvalidArgumentException;
use RuntimeCheck\Enum\Status;
use RuntimeCheck\Type\AmountReadProcessor;
use RuntimeCheckType\Amount;

/**
 * Turns raw input into pending Page changes.
 */
final readonly class PageInput
{
    public function __construct(
        private ValueDecoder $decode,
        private AmountReadProcessor $amountReader,
    ) {
    }

    private function title(mixed $value): ?string
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Page.title');
    }

    private function slug(mixed $value): ?string
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Page.slug');
    }

    private function content(mixed $value): ?string
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Page.content');
    }

    private function excerpt(mixed $value): ?string
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Page.excerpt');
    }

    private function status(mixed $value): ?Status
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->enum(Status::class, $value, 'Page.status');
    }

    private function publishedAt(mixed $value): ?DateTimeImmutable
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->datetime($value, 'Page.publishedAt');
    }

    private function enquiryUrl(mixed $value): ?string
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Page.enquiryUrl');
    }

    private function active(mixed $value): ?bool
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->bool($value, 'Page.active');
    }

    private function zero(mixed $value): ?int
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->int($value, 'Page.zero');
    }

    private function disabled(mixed $value): ?bool
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->bool($value, 'Page.disabled');
    }

    private function metadata(mixed $value): ?array
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->json($value, 'Page.metadata');
    }

    private function rank(mixed $value): ?int
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->int($value, 'Page.rank');
    }

    private function amount(mixed $value): ?Amount
    {
        if (null === $value) {
            return null;
        }

        return $this->amountReader->read($this->decode->string($value, 'Page.amount'));
    }

    /**
     * Seeds declared defaults on create and applies explicit input.
     * Absent update keys and existing pending values are not reset by defaults.
     *
     * @param array<string, mixed> $input
     */
    public function apply(MutationBuffer $buffer, array $input): void
    {
        if (array_key_exists('title', $input)) {
            $buffer->set('title', $this->title($input['title']));
        }

        if (array_key_exists('slug', $input)) {
            $buffer->set('slug', $this->slug($input['slug']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('content') && !array_key_exists('content', $input)) {
            $buffer->set('content', $this->content(''));
        }

        if (array_key_exists('content', $input)) {
            $buffer->set('content', $this->content($input['content']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('excerpt') && !array_key_exists('excerpt', $input)) {
            $buffer->set('excerpt', $this->excerpt(''));
        }

        if (array_key_exists('excerpt', $input)) {
            $buffer->set('excerpt', $this->excerpt($input['excerpt']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('status') && !array_key_exists('status', $input)) {
            $buffer->set('status', $this->status(Status::Draft));
        }

        if (array_key_exists('status', $input)) {
            $buffer->set('status', $this->status($input['status']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('publishedAt') && !array_key_exists('publishedAt', $input)) {
            $buffer->set('publishedAt', $this->publishedAt(null));
        }

        if (array_key_exists('publishedAt', $input)) {
            $buffer->set('publishedAt', $this->publishedAt($input['publishedAt']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('enquiryUrl') && !array_key_exists('enquiryUrl', $input)) {
            $buffer->set('enquiryUrl', $this->enquiryUrl(null));
        }

        if (array_key_exists('enquiryUrl', $input)) {
            $buffer->set('enquiryUrl', $this->enquiryUrl($input['enquiryUrl']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('active') && !array_key_exists('active', $input)) {
            $buffer->set('active', $this->active(true));
        }

        if (array_key_exists('active', $input)) {
            $buffer->set('active', $this->active($input['active']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('zero') && !array_key_exists('zero', $input)) {
            $buffer->set('zero', $this->zero(0));
        }

        if (array_key_exists('zero', $input)) {
            $buffer->set('zero', $this->zero($input['zero']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('disabled') && !array_key_exists('disabled', $input)) {
            $buffer->set('disabled', $this->disabled(false));
        }

        if (array_key_exists('disabled', $input)) {
            $buffer->set('disabled', $this->disabled($input['disabled']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('metadata') && !array_key_exists('metadata', $input)) {
            $buffer->set('metadata', $this->metadata('{"source":"default"}'));
        }

        if (array_key_exists('metadata', $input)) {
            $buffer->set('metadata', $this->metadata($input['metadata']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('rank') && !array_key_exists('rank', $input)) {
            $buffer->set('rank', $this->rank(0));
        }

        if (array_key_exists('rank', $input)) {
            $buffer->set('rank', $this->rank($input['rank']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('amount') && !array_key_exists('amount', $input)) {
            $buffer->set('amount', $this->amount('{"cents":10}'));
        }

        if (array_key_exists('amount', $input)) {
            $buffer->set('amount', $this->amount($input['amount']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(string $action, array $args): array
    {
        return match ($action) {
            'publish' => ['at' => $this->decode->datetime($args['at'], 'Page.publish.at')],
            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

