namespace RuntimeCheck\Page;

use Eleph\Runtime\Policy\EntityReadPolicies;
use Eleph\Runtime\Policy\PolicyDecision;
use Eleph\Runtime\Policy\PolicyOutcome;
use Eleph\Runtime\Policy\Viewer;
use RuntimeCheck\Page\Contract\PagePublicReadPolicy;

final readonly class PageReadPolicies implements EntityReadPolicies
{
    public function __construct(
        private PagePublicReadPolicy $publicPolicy,
    ) {
    }

    public function isEmpty(): bool
    {
        return false;
    }

    public function decide(object $entity, Viewer $viewer): PolicyDecision
    {
        assert($entity instanceof Page);
        $decision = $this->publicPolicy->decide($entity, $viewer);
        if (PolicyOutcome::Skip !== $decision->outcome) {
            return $decision->withPolicy('public');
        }

        return PolicyDecision::deny('No policy allowed this read.')->withPolicy('terminal');
    }
}

