use Eleph\Runtime\Verification\Verification;
use RuntimeCheck\Page\Contract\PageEnquiryUrlVerifier;
use RuntimeCheck\Page\Contract\PagePublishedAtVerifier;

/**
 * Dispatches to Page's field verifiers.
 */
final readonly class PageVerifiers implements EntityVerifiers
{
    public function __construct(
        private PagePublishedAtVerifier $publishedAtVerifier,
        private PageEnquiryUrlVerifier $enquiryUrlVerifier,
    ) {
    }

    /**
     * @return list<string>
     */
    public function verifiedFields(): array
    {
        return ['publishedAt', 'enquiryUrl'];
    }

    public function verify(string $field, mixed $value, MutationContext $context): Verification
    {
        return match ($field) {
            'publishedAt' => $this->verifyPublishedAt($value, $context),
            'enquiryUrl' => $this->verifyEnquiryUrl($value, $context),
            default => Verification::ok(),
        };
    }

    private function verifyPublishedAt(mixed $value, MutationContext $context): Verification
    {
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $this->publishedAtVerifier->verify($value, PageMutationContext::of($context));
    }

    private function verifyEnquiryUrl(mixed $value, MutationContext $context): Verification
    {
        assert(null === $value || is_string($value));

        return $this->enquiryUrlVerifier->verify($value, PageMutationContext::of($context));
    }
}

