namespace RuntimeCheck\User;

use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Query\ValueDecoder;
use InvalidArgumentException;
use RuntimeCheck\Enum\Role;

/**
 * Turns raw input into pending User changes.
 */
final readonly class UserInput
{
    public function __construct(
        private ValueDecoder $decode,
    ) {
    }

    private function username(mixed $value): ?string
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'User.username');
    }

    private function role(mixed $value): ?Role
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->enum(Role::class, $value, 'User.role');
    }

    private function active(mixed $value): ?bool
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->bool($value, 'User.active');
    }

    /**
     * Seeds declared defaults on create and applies explicit input.
     * Absent update keys and existing pending values are not reset by defaults.
     *
     * @param array<string, mixed> $input
     */
    public function apply(MutationBuffer $buffer, array $input): void
    {
        if (array_key_exists('username', $input)) {
            $buffer->set('username', $this->username($input['username']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('role') && !array_key_exists('role', $input)) {
            $buffer->set('role', $this->role(Role::Editor));
        }

        if (array_key_exists('role', $input)) {
            $buffer->set('role', $this->role($input['role']));
        }

        if (!$buffer->target()->isPersisted() && !$buffer->isChanged('active') && !array_key_exists('active', $input)) {
            $buffer->set('active', $this->active(true));
        }

        if (array_key_exists('active', $input)) {
            $buffer->set('active', $this->active($input['active']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(string $action, array $args): array
    {
        return match ($action) {

            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

