use Psr\Container\ContainerInterface;
use RuntimeCheck\Page\Contract\PageBySlugQuery;
use RuntimeCheck\Page\Contract\PageEnquiryUrlVerifier;
use RuntimeCheck\Page\Contract\PagePublicReadPolicy;
use RuntimeCheck\Page\Contract\PagePublishedAtVerifier;
use RuntimeCheck\Page\Contract\PageSearchQuery;
use RuntimeCheck\Page\PageFinder;
use RuntimeCheck\Page\PageHydrator;
use RuntimeCheck\Page\PageInput;
use RuntimeCheck\Page\PageReadPolicies;
use RuntimeCheck\Page\PageSideEffects;
use RuntimeCheck\Page\PageVerifiers;
use RuntimeCheck\Page\PageWritePolicies;
use RuntimeCheck\Type\AmountReadProcessor;
use RuntimeCheck\User\UserHydrator;
use RuntimeCheck\User\UserInput;
use RuntimeCheck\User\UserReadPolicies;
use RuntimeCheck\User\UserSideEffects;
use RuntimeCheck\User\UserVerifiers;
use RuntimeCheck\User\UserWritePolicies;

/**
 * Every generated class this project's container must be able to build.
 */
final class Wiring
{
    /**
     * The hand-written Contract bindings are not here: BootCheck enforces those
     * separately, against contracts() on the catalogue.
     *
     * @return array<class-string, Closure(ContainerInterface): object>
     */
    public static function registrations(): array
    {
        return [
            PageHydrator::class => static fn (ContainerInterface $c): object => new PageHydrator(self::resolve($c, ValueDecoder::class), self::resolve($c, AmountReadProcessor::class)),
            PageInput::class => static fn (ContainerInterface $c): object => new PageInput(self::resolve($c, ValueDecoder::class), self::resolve($c, AmountReadProcessor::class)),
            PageSideEffects::class => static fn (ContainerInterface $c): object => new PageSideEffects(),
            PageVerifiers::class => static fn (ContainerInterface $c): object => new PageVerifiers(self::resolve($c, PagePublishedAtVerifier::class), self::resolve($c, PageEnquiryUrlVerifier::class)),
            PageReadPolicies::class => static fn (ContainerInterface $c): object => new PageReadPolicies(self::resolve($c, PagePublicReadPolicy::class)),
            PageWritePolicies::class => static fn (ContainerInterface $c): object => new PageWritePolicies(),
            PageFinder::class => static fn (ContainerInterface $c): object => new PageFinder(self::resolve($c, PageBySlugQuery::class), self::resolve($c, PageSearchQuery::class)),
            UserHydrator::class => static fn (ContainerInterface $c): object => new UserHydrator(self::resolve($c, ValueDecoder::class)),
            UserInput::class => static fn (ContainerInterface $c): object => new UserInput(self::resolve($c, ValueDecoder::class)),
            UserSideEffects::class => static fn (ContainerInterface $c): object => new UserSideEffects(),
            UserVerifiers::class => static fn (ContainerInterface $c): object => new UserVerifiers(),
            UserReadPolicies::class => static fn (ContainerInterface $c): object => new UserReadPolicies(),
            UserWritePolicies::class => static fn (ContainerInterface $c): object => new UserWritePolicies(),
        ];
    }

    /**
     * @template T of object
     * @param class-string<T> $class
     * @return T
     */
    private static function resolve(ContainerInterface $c, string $class): object
    {
        $service = $c->get($class);

        assert($service instanceof $class);

        return $service;
    }
}
